public static <V, E> IsomorphicGraphMapping<V, E> identity(Graph<V, E> graph) {
    if (graph == null) {
        throw new IllegalArgumentException("Graph cannot be null");
    }

    // Create a mapping from the graph to itself
    IsomorphicGraphMapping<V, E> mapping = new IsomorphicGraphMapping<V, E>();

    // Add a mapping for each vertex in the graph
    for (V vertex : graph.getVertices()) {
        mapping.addMapping(vertex, vertex);
    }

    // Add a mapping for each edge in the graph
    for (E edge : graph.getEdges()) {
        V source = graph.getEdgeSource(edge);
        V target = graph.getEdgeTarget(edge);
        mapping.addMapping(source, target);
    }

    return mapping;
}

