public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }

    ParameterizedType parameterizedType = (ParameterizedType) genericType;
    Type[] typeArguments = parameterizedType.getActualTypeArguments();
    Class<?>[] resolvedArguments = new Class<?>[typeArguments.length];

    for (int i = 0; i < typeArguments.length; i++) {
        Type typeArgument = typeArguments[i];
        if (typeArgument instanceof Class) {
            resolvedArguments[i] = (Class<?>) typeArgument;
        } else if (typeArgument instanceof TypeVariable) {
            TypeVariable<?> typeVariable = (TypeVariable<?>) typeArgument;
            // Search for a bound type in the target type that matches the name of the type variable
            // If no bound type is found, return null
            String typeVariableName = typeVariable.getName();
            if (targetType.getTypeParameters() != null) {
                for (TypeParameterElement typeParameterElement : targetType.getTypeParameters()) {
                    if (typeParameterElement.getSimpleName().toString().equals(typeVariableName)) {
                        resolvedArguments[i] = typeParameterElement.asType();
                        break;
                    }
                }
            }
        }

        if (resolvedArguments[i] == null) {
            return null;
        }
    }

    return resolvedArguments;
}

public void accept(METRICS data) {
    // Check for null values and handle edge cases
    if (data == null) {
        throw new IllegalArgumentException("Null data is not allowed");
    }

    // Lock the cache to avoid concurrency issues
    synchronized (cache) {
        // Check if the given data already exists in the cache
        if (cache.containsKey(data.getId())) {
            METRICS existingData = cache.get(data.getId());
            // Merge the existing data with the new data
            METRICS mergedData = new METRICS(existingData.getValue() + data.getValue(), data.getTimestamp());
            // Replace the existing data in the cache with the merged data
            cache.put(data.getId(), mergedData);
        } else {
            // Add the given data to the cache
            cache.put(data.getId(), data);
        }
    }
}

