public static int computeUTF8Size(CharSequence str, int index, int len) {
    if (str == null) {
      throw new IllegalArgumentException("str must not be null");
    }
    if (index < 0 || index > str.length()) {
      throw new IllegalArgumentException("index must be between 0 and str.length()");
    }
    if (len < 0 || len > str.length() - index) {
      throw new IllegalArgumentException("len must be between 0 and str.length() - index");
    }

    int byteSize = 0;
    for (int i = index; i < index + len; i++) {
      char c = str.charAt(i);
      if (c <= 0x7F) {
        byteSize += 1;
      } else if (c <= 0x7FF) {
        byteSize += 2;
      } else if (Character.isHighSurrogate(c)) {
        i++;
        if (!Character.isLowSurrogate(str.charAt(i))) {
          throw new IllegalArgumentException("string contains invalid surrogate pair");
        }
        byteSize += 4;
      } else {
        byteSize += 3;
      }
    }
    return byteSize;
  }

