public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
        List<PathSegmentImpl> pathSegments = new ArrayList<>();

        // Check if the URI is null
        if (u == null) {
            throw new NullPointerException("URI cannot be null");
        }

        // Check if the URI path is null or empty
        if (u.getPath() == null || u.getPath().isEmpty()) {
            return pathSegments;
        }

        // Split the path component of the URI
        String[] pathSegmentsRaw = u.getPath().split("/");

        // Iterate through the split path segments
        for (String pathSegmentRaw : pathSegmentsRaw) {
            // Check if the path segment is null or empty
            if (pathSegmentRaw == null || pathSegmentRaw.isEmpty()) {
                continue;
            }

            // Create a new path segment
            PathSegmentImpl pathSegment = new PathSegmentImpl();
            pathSegment.setValue(pathSegmentRaw);

            // Decode the path segment if needed
            if (decode) {
                pathSegment.setValue(decode(pathSegment.getValue()));
            }

            // Add the path segment to the list
            pathSegments.add(pathSegment);
        }

        return pathSegments;
    }

