public static Pair<Box2D,Box2D> splitAlongXAxis(Box2D box){
    // Calculate the centroid of the box
    double centroidX = (box.minX + box.maxX) / 2;

    // Calculate the half-width of the box
    double halfWidth = (box.maxX - centroidX) / 2;

    // Create the two resulting boxes
    Box2D leftBox = new Box2D(centroidX - halfWidth, box.minY, centroidX + halfWidth, box.maxY);
    Box2D rightBox = new Box2D(centroidX + halfWidth, box.minY, centroidX + halfWidth, box.maxY);

    // Return a pair with the two resulting boxes
    return new Pair<>(leftBox, rightBox);
}

public void enlarge(final int size) {
    // Check if the current capacity of the byte vector is less than the required size
    if (capacity() < size) {
        // Calculate the new capacity based on the current capacity and the required size
        int newCapacity = (int) Math.max(Math.ceil(capacity() * 1.5), size);
        // Create a new byte array with the calculated capacity
        byte[] newContent = new byte[newCapacity];
        // Copy the old content of the byte vector into the new byte array
        System.arraycopy(content, 0, newContent, 0, content.length);
        // Replace the old content of the byte vector with the new byte array
        content = newContent;
    }
}

