public static String trimTrailingWhitespace(String str) {
    // Check if the string is null or empty
    if (str == null || str.isEmpty()) {
        return str;
    }

    // Trim any trailing whitespace characters
    int lastNonWhitespaceIndex = str.length() - 1;
    for (int i = lastNonWhitespaceIndex; i >= 0; i--) {
        if (!Character.isWhitespace(str.charAt(i))) {
            break;
        }
        lastNonWhitespaceIndex--;
    }

    // If the last non-whitespace character is not the last character in the string
    // then return a new string containing the trimmed characters.
    // Otherwise, just return the original string.
    return lastNonWhitespaceIndex < str.length() - 1
            ? str.substring(0, lastNonWhitespaceIndex + 1)
            : str;
}

