        return null;
    }
    StringBuilder builder = new StringBuilder();
    for (int i = 0; i < str.length(); i++) {
        char c = str.charAt(i);
        if (c == '\\' && i < str.length() - 1) {
            char nextChar = str.charAt(i + 1);
            if (nextChar == 'n') {
                builder.append('\n');
                i++;
            } else if (nextChar == 't') {
                builder.append('\t');
                i++;
            } else {
                builder.append(c);
            }
        } else {
            builder.append(c);
        }
    }
    return builder.toString();
}

