public String readUtf(int constantPoolEntryIndex, char[] charBuffer) {
    // Read the tag of the constant pool entry
    int tag = readUnsignedByte(constantPoolEntryIndex);

    // Check if the tag is for a CONSTANT_Utf8 entry
    if (tag == CONSTANT_Utf8) {
        // Read the length of the string
        int length = readUnsignedShort(constantPoolEntryIndex + 1);

        // Check if the char buffer is large enough to hold the string
        if (charBuffer.length < length) {
            // Resize the char buffer if needed
            charBuffer = Arrays.copyOf(charBuffer, length);
        }

        // Read the string into the char buffer
        charBuffer.read(constantPoolEntryIndex + 3, length);

        // Return the string
        return new String(charBuffer, 0, length);
    } else {
        // Throw an exception if the tag is not for a CONSTANT_Utf8 entry
        throw new RuntimeException("Invalid tag: " + tag);
    }
}

