      // Check the input characterRange
      if (c >= '0' && c <= '9') {
          // If it is a number, calculate the numeric value
          return (char) (c - '0');
      } else if (c >= 'a' && c <= 'f') {
          // If it is a lowercase letter, calculate the numeric value
          return (char) (c - 'a' + 10);
      } else if (c >= 'A' && c <= 'F') {
          // If it is an uppercase letter, calculate the numeric value
          return (char) (c - 'A' + 10);
      } else {
          // If it is an unknown character, return maximum value
          return Character.MAX_VALUE;
      }
  }

