private void check(String modelName) throws IllegalStateException {
    if (modelName == null) {
        throw new IllegalArgumentException("Model name cannot be null");
    }

    if (modelName.equals("")) {
        throw new IllegalArgumentException("Model name cannot be empty");
    }

    if (!modelName.matches("[a-zA-Z_]+")) {
        throw new IllegalArgumentException("Model name must only contain letters and underscores");
    }

    if (modelName.matches("([a-z_])*([A-Z])+") || modelName.matches("([A-Z])+([a-z_])*")) {
        throw new IllegalArgumentException("Model name must start with a letter and contain only underscores");
    }

    if (modelName.startsWith("_")) {
        throw new IllegalArgumentException("Model name cannot start with an underscore");
    }

    if (modelName.endsWith("_")) {
        throw new IllegalArgumentException("Model name cannot end with an underscore");
    }
}

public byte readByte() throws IOException {
    // Check if there is still data available in the buffer
    if (buffer.hasRemaining()) {
        // Return the next byte from the buffer
        return buffer.get();
    } else {
        // Refill the buffer
        fillBuffer();

        // If the buffer is still empty, throw an IOException
        if (!buffer.hasRemaining()) {
            throw new IOException("No more data available");
        }

        // Return the next byte from the buffer
        return buffer.get();
    }
}

