@Override
protected Vertex provideNextVertex() {
    // Get the current depth of the search
    int currentDepth = getCurrentDepth();

    // Get the vertices that have not been explored
    List<Vertex> unexploredVertices = getUnexploredVertices();

    // Find the vertex with the lowest depth which has not been explored
    Vertex nextVertex = null;
    for (Vertex vertex : unexploredVertices) {
        if (vertex.getDepth() == currentDepth && vertex.getStatus() == VertexStatus.UNEXPLORED) {
            nextVertex = vertex;
            break;
        }
    }

    // If no vertex was found, get the vertex with the lowest depth regardless of its status
    if (nextVertex == null) {
        nextVertex = unexploredVertices.stream()
                .min(Comparator.comparingInt(Vertex::getDepth))
                .orElse(null);
