                    this.names.remove(normalizedOldName);
                }

                this.names.put(normalizedNewName, this.values.get(normalizedOldName));
            });
        } else {
            // If the column is not hot, just replace the name immediately
            String normalizedOldName = normalizeName(oldName);
            String normalizedNewName = normalizeName(newName);
            if (normalizedOldName.equals(normalizedNewName)) {
                throw new IllegalArgumentException("Invalid name replacement: '" + newName + "' is not a new name");
            }

            this.names.put(normalizedNewName, this.names.get(normalizedOldName));
            this.names.remove(normalizedOldName);
