public boolean unlink(ListNodeImpl<E> node) {
    if (node == null) {
        return false;
    }

    if (node.equals(head)) {
        head = head.next;
    }

    if (node.equals(tail)) {
        tail = tail.prev;
    }

    node.prev.next = node.next;
    node.next.prev = node.prev;

    node.next = null;
    node.prev = null;

    return true;
}

