public void moveAllListNodes(DoublyLinkedList<E> list) {
    // Check for null values and edge cases
    if (list == null || list.isEmpty()) {
        return;
    }

    // Create a temporary variable to store the first node of the list
    ListNode<E> firstNode = list.getFirstNode();

    // Remove the first node from the list and add it to this list
    list.removeFirstNode();
    addListNode(firstNode);

    // While there are still nodes left in the list
    while (list.getListSize() != 0) {
        // Remove the next node from the list and add it to this list
        ListNode<E> nextNode = list.getNextNode(firstNode);
        list.removeListNode(nextNode);
        addListNode(nextNode);

        // Make the first node the next node
        firstNode = nextNode;
    }
}

