public static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    // Check if the given vertices are valid
    if (vertices == null || vertices.isEmpty()) {
        return false;
    }

    // Check if the subgraph is valid
    for (V vertex : vertices) {
        if (!graph.containsVertex(vertex)) {
            return false;
        }
    }

    // Check if all vertices are connected to each other
    for (V vertex1 : vertices) {
        for (V vertex2 : vertices) {
            if (!graph.containsEdge(vertex1, vertex2)) {
                return false;
            }
        }
    }

    return true;
}

