public int readTag() throws IOException {
    int tag;
    while (true) {
        tag = input.read();
        if (tag == -1) {
            return 0;
        } else if (tag >= 0 && tag <= 127) {
            return tag;
        } else if (tag >= 192 && tag <= 223) {
            int continuationByte = input.read();
            if (continuationByte >= 128 && continuationByte <= 191) {
                return (tag - 192) * 64 + continuationByte - 128;
            } else {
                throw new IOException("Invalid continuation byte: " + continuationByte);
            }
        } else if (tag >= 224 && tag <= 239) {
            int firstByte = input.read();
            if (firstByte >= 128 && firstByte <= 191) {
                int secondByte = input.read();
                if (secondByte >= 128 && secondByte <= 191) {
                    return (tag - 224) * 4096 + (firstByte - 128) * 64 + secondByte - 128;
                } else {
                    throw new IOException("Invalid second byte: " + secondByte);
                }
            } else {
                throw new IOException("Invalid first byte: " + firstByte);
            }
        } else {
            throw new IOException("Invalid tag: " + tag);
        }
    }
}

